javascript:void(function(){ var VER='5034499a'; if(window.__IBON_WATCH){ if(window.__IBON_WATCH.ver===VER){window.__IBON_WATCH.toggle();return} alert('頁面上還有舊版的釋票提醒工具。\n請先重新整理（F5）頁面，再點一次書籤。'); return; } var LS='__ibon_watch_cfg'; var C={interval:10,sound:true}; try{ var saved=JSON.parse(localStorage.getItem(LS)||'null'); if(saved){ if(typeof saved.interval==='number')C.interval=saved.interval; if(typeof saved.sound==='boolean')C.sound=saved.sound; } }catch(e){} function saveCfg(){try{localStorage.setItem(LS,JSON.stringify(C))}catch(e){}} var ST={running:false,timer:null,checks:0,fails:0,alerting:false,audio:null,titleTimer:null,origTitle:document.title}; var panel=document.createElement('div'); panel.id='__ibon_panel'; panel.innerHTML=` <style> #__ibon_panel{ position:fixed;bottom:16px;right:12px;z-index:2147483647; width:300px;max-width:calc(100vw - 24px); background:#12141c;color:#e2e4ea;border:1px solid #2a2e3d; border-radius:12px;font-family:-apple-system,sans-serif;font-size:13px; box-shadow:0 8px 32px rgba(0,0,0,.5);overflow:hidden; } #__ibon_panel *{box-sizing:border-box;margin:0;padding:0} #__ibon_panel .ip-head{ display:flex;align-items:center;justify-content:space-between; padding:10px 14px;background:#1a1d2a;cursor:move;touch-action:none; } #__ibon_panel .ip-head b{font-size:14px;color:#f472b6} #__ibon_panel .ip-head div{display:flex;gap:6px} #__ibon_panel .ip-x{width:26px;height:26px;border:none;border-radius:6px;background:#2a2e3d;color:#e2e4ea;font-size:15px;cursor:pointer} #__ibon_panel .ip-body{padding:12px 14px} #__ibon_panel .ip-status{background:#1a1d2a;border-radius:8px;padding:10px;margin-bottom:10px;text-align:center} #__ibon_panel .ip-status b{font-size:16px} #__ibon_panel .ip-row{display:flex;gap:8px;align-items:center;margin-bottom:10px} #__ibon_panel .ip-row label{font-size:12px;color:#8b8fa3;white-space:nowrap} #__ibon_panel .ip-row input{width:60px;padding:6px;background:#0c0e14;border:1px solid #2a2e3d;color:#e2e4ea;border-radius:6px;font-size:13px} #__ibon_panel .ip-btn{width:100%25;padding:10px;border:none;border-radius:8px;font-size:14px;font-weight:600;cursor:pointer;margin-bottom:6px} #__ibon_panel .ip-go{background:#f472b6;color:#0c0e14} #__ibon_panel .ip-stop{background:#f87171;color:#fff} #__ibon_panel .ip-ack{background:#4ade80;color:#0c0e14} #__ibon_panel .ip-log{font-family:ui-monospace,monospace;font-size:11px;line-height:1.5;max-height:140px;overflow-y:auto;background:#0c0e14;border-radius:6px;padding:8px;margin-top:8px} #__ibon_panel .ip-log .ok{color:#4ade80} #__ibon_panel .ip-log .warn{color:#fbbf24} #__ibon_banner{ position:fixed;top:0;left:0;right:0;z-index:2147483647; background:#f472b6;color:#0c0e14;font-family:-apple-system,sans-serif; font-size:20px;font-weight:800;text-align:center;padding:18px 12px; box-shadow:0 4px 20px rgba(0,0,0,.6);display:none; } </style> <div class="ip-head" id="__ip_head"> <b>ibon 釋票提醒</b> <div><button class="ip-x" id="__ip_mini" title="縮小">—</button><button class="ip-x" id="__ip_close">&times;</button></div> </div> <div class="ip-body"> <div class="ip-status">狀態：<b id="__ip_state">待機</b></div> <div class="ip-row"> <label>每幾秒檢查</label> <input type="number" id="__ip_int" min="5" step="1"> <label><input type="checkbox" id="__ip_snd" style="width:auto"> 響鈴</label> </div> <button class="ip-btn ip-go" id="__ip_start">開始監看</button> <button class="ip-btn ip-stop" id="__ip_stopbtn" style="display:none">停止監看</button> <button class="ip-btn ip-ack" id="__ip_ack" style="display:none">我知道了（停止響鈴）</button> <div class="ip-log" id="__ip_log"></div> </div> `; document.body.appendChild(panel); var banner=document.createElement('div'); banner.id='__ibon_banner'; document.body.appendChild(banner); var fab=document.createElement('div'); fab.id='__ibon_fab'; fab.style.cssText='position:fixed;bottom:16px;right:16px;z-index:2147483647;width:52px;height:52px;border-radius:50%25;background:#12141c;border:2px solid #f472b6;color:#f472b6;font-size:22px;display:none;align-items:center;justify-content:center;cursor:pointer;box-shadow:0 4px 16px rgba(0,0,0,.6)'; fab.textContent='🔔'; document.body.appendChild(fab); function $(id){return document.getElementById(id)} function log(msg,cls){ var box=$('__ip_log'); var d=document.createElement('div'); d.className=cls||''; var n=new Date(); var ts=('0'+n.getHours()).slice(-2)+':'+('0'+n.getMinutes()).slice(-2)+':'+('0'+n.getSeconds()).slice(-2); d.textContent=ts+' '+msg; box.appendChild(d); if(box.children.length>100)box.removeChild(box.firstChild); box.scrollTop=box.scrollHeight; } $('__ip_int').value=C.interval; $('__ip_snd').checked=C.sound; function beepStart(){ try{ var Ctx=window.AudioContext||window.webkitAudioContext; if(!Ctx)return; if(!ST.audio)ST.audio=new Ctx(); var ctx=ST.audio; if(ctx.state==='suspended')ctx.resume(); ST.beepTimer=setInterval(function(){ var o=ctx.createOscillator(); var g=ctx.createGain(); o.type='square'; o.frequency.value=880; g.gain.value=0.15; o.connect(g);g.connect(ctx.destination); o.start(); o.stop(ctx.currentTime+0.25); },500); }catch(e){} } function beepStop(){ if(ST.beepTimer){clearInterval(ST.beepTimer);ST.beepTimer=null} } function flashTitleStart(){ var on=false; ST.titleTimer=setInterval(function(){ document.title=on?ST.origTitle:'🔔 有票了！'; on=!on; },700); } function flashTitleStop(){ if(ST.titleTimer){clearInterval(ST.titleTimer);ST.titleTimer=null;document.title=ST.origTitle} } function detect(html){ try{ var doc=new DOMParser().parseFromString(html,'text/html'); var grid=doc.getElementById('ctl00_ContentPlaceHolder1_DataGrid'); if(!grid)return{ok:false,reason:'找不到售票表格（可能登入逾時或頁面已跳轉），請回頁面重新進入票區'}; var rows=grid.querySelectorAll('tbody tr'); if(!rows.length)return{ok:false,reason:'表格沒有資料列'}; var avail=false,detail=[]; for(var i=0;i<rows.length;i++){ var cells=rows[i].querySelectorAll('td'); var name=cells[0]?cells[0].textContent.trim():''; var action=rows[i].querySelector('td.action')||cells[cells.length-1]; var txt=action?action.textContent.trim().replace(/\s+/g,' '):''; var sel=action?action.querySelector('select:not([disabled]),input:not([disabled])'):null; var sold=/售完|完售|無票|額滿|未開賣/.test(txt); var rowAvail=(!!sel&&!sold)||(!sold&&txt!==''&&!/^0+$/.test(txt)); if(rowAvail)avail=true; detail.push(name+'：'+(rowAvail?'可購買':(txt||'?'))); } return{ok:true,avail:avail,detail:detail.join(' ｜ ')}; }catch(e){return{ok:false,reason:'解析失敗：'+e.message}} } async function checkOnce(){ ST.checks++; var url=location.pathname+location.search; try{ var res=await fetch(url,{credentials:'include',cache:'no-store'}); if(!res.ok){ST.fails++;log('第'+ST.checks+'次：HTTP '+res.status,'warn');afterFail();return} var html=await res.text(); var d=detect(html); if(!d.ok){ST.fails++;log('第'+ST.checks+'次：'+d.reason,'warn');afterFail();return} ST.fails=0; if(d.avail){ log('第'+ST.checks+'次：有票！'+d.detail,'ok'); fire(d.detail); }else{ log('第'+ST.checks+'次：售完（'+d.detail+'）'); } }catch(e){ ST.fails++; log('第'+ST.checks+'次：連線失敗 '+e.message,'warn'); afterFail(); } } function afterFail(){ if(ST.fails>=5){ log('連續 5 次抓不到資料，暫停監看，請確認仍在票區頁面且已登入','warn'); stopWatch(); } } function fire(detail){ if(ST.alerting)return; ST.alerting=true; stopWatch(true); $('__ip_state').textContent='有票了！'; $('__ip_state').style.color='#4ade80'; $('__ip_ack').style.display=''; banner.textContent='🔔 有票了！'+detail+'　請立即手動搶購（本工具不會自動買）'; banner.style.display='block'; if(C.sound)beepStart(); flashTitleStart(); try{if('vibrate' in navigator)navigator.vibrate([400,200,400,200,600])}catch(e){} try{if(window.Notification&&Notification.permission==='granted')new Notification('ibon 有票了！',{body:detail})}catch(e){} if(panel.style.display==='none'){fab.style.display='none';panel.style.display=''} } function ackAlert(){ ST.alerting=false; beepStop(); flashTitleStop(); banner.style.display='none'; $('__ip_ack').style.display='none'; $('__ip_state').textContent='待機'; $('__ip_state').style.color=''; try{if('vibrate' in navigator)navigator.vibrate(0)}catch(e){} } function startWatch(){ if(ST.running)return; C.interval=Math.max(5,parseInt($('__ip_int').value)||10); C.sound=$('__ip_snd').checked; $('__ip_int').value=C.interval; saveCfg(); if(location.host.indexOf('ibon')===-1)log('注意：目前不在 ibon 網域，仍會嘗試監看','warn'); try{if(window.Notification&&Notification.permission==='default')Notification.requestPermission()}catch(e){} if(C.sound){try{var Ctx=window.AudioContext||window.webkitAudioContext;if(Ctx){if(!ST.audio)ST.audio=new Ctx();if(ST.audio.state==='suspended')ST.audio.resume()}}catch(e){}} ST.running=true;ST.checks=0;ST.fails=0; $('__ip_start').style.display='none'; $('__ip_stopbtn').style.display=''; $('__ip_state').textContent='監看中…'; $('__ip_state').style.color='#f472b6'; log('開始監看，每 '+C.interval+' 秒檢查一次','ok'); checkOnce(); ST.timer=setInterval(checkOnce,C.interval*1000); } function stopWatch(keepState){ if(ST.timer){clearInterval(ST.timer);ST.timer=null} ST.running=false; $('__ip_start').style.display=''; $('__ip_stopbtn').style.display='none'; if(!keepState){ $('__ip_state').textContent='待機'; $('__ip_state').style.color=''; log('已停止監看'); } } $('__ip_start').addEventListener('click',startWatch); $('__ip_stopbtn').addEventListener('click',function(){stopWatch()}); $('__ip_ack').addEventListener('click',ackAlert); $('__ip_close').addEventListener('click',function(){stopWatch();beepStop();flashTitleStop();banner.style.display='none';panel.style.display='none';fab.style.display='none'}); $('__ip_mini').addEventListener('click',function(e){e.stopPropagation();panel.style.display='none';fab.style.display='flex'}); fab.addEventListener('click',function(){fab.style.display='none';panel.style.display=''}); (function(){ var head=$('__ip_head'),sx,sy,ox,oy,drag=false; function down(e){ if(e.target.closest&&e.target.closest('button'))return; drag=true; var ev=e.touches?e.touches[0]:e; sx=ev.clientX;sy=ev.clientY; var r=panel.getBoundingClientRect();ox=r.left;oy=r.top; e.preventDefault(); } function move(e){ if(!drag)return; var ev=e.touches?e.touches[0]:e; panel.style.left=(ox+ev.clientX-sx)+'px'; panel.style.top=(oy+ev.clientY-sy)+'px'; panel.style.right='auto';panel.style.bottom='auto'; } function up(){drag=false} head.addEventListener('mousedown',down); head.addEventListener('touchstart',down,{passive:false}); document.addEventListener('mousemove',move); document.addEventListener('touchmove',move,{passive:false}); document.addEventListener('mouseup',up); document.addEventListener('touchend',up); })(); window.__IBON_WATCH={ver:VER,toggle:function(){ if(panel.style.display==='none'){fab.style.display='none';panel.style.display=''} else{panel.style.display='none';fab.style.display='flex'} }}; log('提醒工具已載入。設定秒數後按「開始監看」。'); log('只監看、不自動購買；有票後請自己搶購。'); }());